def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    A = list(map(int, data[1:N+1]))

    number_count = {}

    for number in A:
        if number in number_count:
            number_count[number] += 1
        else:
            number_count[number] = 1

    result = 0
    for count in number_count.values():
        if count % 2 == 1:
            result += 1

    print(result)

if __name__ == "__main__":
    main()

